      "finding_id": "DD-1",
      "drift_kind": "name",
      "explanation": "The IfRange.check docstring refers to an attribute named `datetime`, but the IfRange class stores and exposes this value as `date`.",
      "doc_citation": {
        "path": "werkzeug/src/werkzeug/datastructures/range.py",
        "start_line": 37,
        "end_line": 39,
        "quote": "If :attr:`etag` is set, the strong comparison function is used with\n        :attr:`.Response.etag`. If :attr:`datetime` is set, it must equal\n        :attr:`.Response.last_modified`."
      },
      "code_citation": {
        "path": "werkzeug/src/werkzeug/datastructures/range.py",
        "start_line": 31,
        "end_line": 31,
        "quote": "        self.date = date"
      },
      "proposed_fix": "In werkzeug/src/werkzeug/datastructures/range.py, change `:attr:`datetime`` to `:attr:`date`` in the IfRange.check docstring."
    },
    {
      "finding_id": "DD-2",
      "drift_kind": "name",
      "explanation": "The EnvironBuilder.files docstring references `FileMultiDict.close`, but the corresponding class implemented in this repository is named `StreamMultiDict`.",
      "doc_citation": {
        "path": "werkzeug/src/werkzeug/test.py",
        "start_line": 555,
        "end_line": 556,
        "quote": "        Setting this will _not_ close files in the previous dict, call\n        :meth:`.FileMultiDict.close` first if that's needed."
      },
      "code_citation": {
        "path": "werkzeug/src/werkzeug/datastructures/file_storage.py",
        "start_line": 159,
        "end_line": 159,
        "quote": "class StreamMultiDict(MultiDict[str, FileStorage]):"
      },
      "proposed_fix": "In werkzeug/src/werkzeug/test.py, change `:meth:`.FileMultiDict.close`` to `:meth:`.StreamMultiDict.close``."
    }
  ],
  "atlas_claims": []
}
